"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import type { AuthUser } from "@/lib/types";
import type { LucideIcon } from "lucide-react";
import {
  LayoutDashboard,
  Users,
  Database,
  Shield,
  UserCog,
  LogOut,
  ChevronUp,
  User,
  Menu,
  X,
} from "lucide-react";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

type MenuSection = {
  label?: string;
  items: { icon: LucideIcon; label: string; href: string; resource: string }[];
};

const ADMIN_MENU: MenuSection[] = [
  {
    items: [
      { icon: LayoutDashboard, label: "채용현황", href: "/dashboard", resource: "dashboard" },
      { icon: Users, label: "후보자 관리", href: "/candidates", resource: "candidates" },
      { icon: Database, label: "데이터 관리", href: "/data", resource: "admin.data" },
    ],
  },
  {
    label: "시스템",
    items: [
      { icon: Shield, label: "권한 관리", href: "/permissions", resource: "system.permissions" },
      { icon: UserCog, label: "사용자 관리", href: "/users", resource: "system.users" },
    ],
  },
];

const DEAN_MENU: MenuSection[] = [
  {
    items: [
      { icon: LayoutDashboard, label: "채용현황", href: "/dashboard", resource: "dashboard" },
      { icon: Users, label: "후보자 관리", href: "/candidates", resource: "candidates" },
    ],
  },
];

function UserMenu({ user }: { user: AuthUser }) {
  const [open, setOpen] = useState(false);
  const router = useRouter();

  async function handleLogout() {
    await fetch("/api/auth/logout", { method: "POST" });
    router.push("/login");
    router.refresh();
  }

  return (
    <div style={{ position: "relative", borderTop: "1px solid rgba(255,255,255,0.08)" }}>
      {/* Popup */}
      {open && (
        <div
          style={{
            position: "absolute",
            bottom: "100%",
            left: 8,
            right: 8,
            background: "#142e20",
            borderRadius: 8,
            padding: "8px 0",
            marginBottom: 4,
            boxShadow: "0 -4px 16px rgba(0,0,0,0.3)",
          }}
        >
          <div style={{ padding: "10px 16px", borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
            <div style={{ fontSize: 12, fontWeight: 600, color: "#fff" }}>{user.username}</div>
            <div style={{ fontSize: 10, color: "var(--sidebar-text)", marginTop: 2 }}>
              역할: {user.role}
            </div>
            {user.departmentCode && (
              <div style={{ fontSize: 10, color: "var(--sidebar-text)", marginTop: 1 }}>
                학과: {user.departmentCode}
              </div>
            )}
          </div>
          <button
            onClick={handleLogout}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              width: "100%",
              padding: "10px 16px",
              background: "transparent",
              border: "none",
              color: "#e74c3c",
              fontSize: 12,
              cursor: "pointer",
              textAlign: "left",
            }}
          >
            <LogOut size={14} />
            로그아웃
          </button>
        </div>
      )}

      {/* Toggle button */}
      <button
        onClick={() => setOpen(!open)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 10,
          width: "100%",
          padding: "16px 16px",
          background: "transparent",
          border: "none",
          cursor: "pointer",
          textAlign: "left",
        }}
      >
        <div
          style={{
            width: 30,
            height: 30,
            borderRadius: "50%",
            background: "var(--primary-green)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          <User size={14} color="#fff" />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12, fontWeight: 600, color: "var(--sidebar-text-active)" }}>
            {user.username}
          </div>
          <div style={{ fontSize: 10, color: "var(--sidebar-text)", marginTop: 1 }}>
            {user.role}
          </div>
        </div>
        <ChevronUp
          size={14}
          color="var(--sidebar-text)"
          style={{
            transform: open ? "rotate(180deg)" : "rotate(0deg)",
            transition: "transform 0.2s",
          }}
        />
      </button>
    </div>
  );
}

function getMenuForRole(role: string): MenuSection[] {
  if (role === "DEAN") return DEAN_MENU;
  return ADMIN_MENU; // ADMIN and VIP get the same menu
}

function filterMenuByResources(
  menu: MenuSection[],
  viewableResources: string[]
): MenuSection[] {
  return menu
    .map((section) => ({
      ...section,
      items: section.items.filter((item) =>
        viewableResources.includes(item.resource)
      ),
    }))
    .filter((section) => section.items.length > 0);
}

function isActive(pathname: string, href: string): boolean {
  if (href === "/") return pathname === "/";
  return pathname === href || pathname.startsWith(href + "/");
}

function MenuContent({
  menu,
  pathname,
  onItemClick,
}: {
  menu: MenuSection[];
  pathname: string;
  onItemClick?: () => void;
}) {
  return (
    <nav style={{ flex: 1, padding: "0 8px" }}>
      {menu.map((section, sIdx) => (
        <div key={sIdx}>
          {section.label && (
            <div
              style={{
                fontSize: 10,
                fontWeight: 600,
                color: "var(--sidebar-section)",
                textTransform: "uppercase",
                padding: "20px 12px 6px",
                letterSpacing: "0.05em",
              }}
            >
              {section.label}
            </div>
          )}
          {section.items.map((item) => {
            const active = isActive(pathname, item.href);
            const IconComponent = item.icon;
            return (
              <Link
                key={item.href}
                href={item.href}
                onClick={onItemClick}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  padding: "10px 14px",
                  marginBottom: 3,
                  borderRadius: 6,
                  fontSize: 13,
                  fontWeight: active ? 600 : 400,
                  color: active
                    ? "var(--sidebar-text-active)"
                    : "var(--sidebar-text)",
                  background: active ? "var(--sidebar-hover)" : "transparent",
                  textDecoration: "none",
                  transition: "background 0.15s, color 0.15s",
                }}
              >
                <IconComponent
                  size={17}
                  style={{ flexShrink: 0 }}
                  color={
                    active
                      ? "var(--sidebar-text-active)"
                      : "var(--sidebar-text)"
                  }
                />
                {item.label}
              </Link>
            );
          })}
        </div>
      ))}
    </nav>
  );
}

function LogoBlock() {
  return (
    <div style={{ padding: "0 16px 28px", display: "flex", flexDirection: "column", alignItems: "center" }}>
      <div
        style={{
          width: 40,
          height: 40,
          borderRadius: "50%",
          background: "rgba(255,255,255,0.85)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          marginBottom: 10,
        }}
      >
        <Image
          src="/logo_SKKU_colored.png"
          alt="SKKU"
          width={28}
          height={28}
          style={{ objectFit: "contain" }}
          unoptimized
        />
      </div>
      <div
        style={{
          fontWeight: 700,
          fontSize: 13,
          color: "var(--sidebar-text-active)",
          textAlign: "center",
          lineHeight: 1.2,
        }}
      >
        성균관대학교
      </div>
      <div
        style={{
          fontSize: 11,
          fontWeight: 500,
          color: "var(--sidebar-text)",
          marginTop: 3,
          textAlign: "center",
        }}
      >
        교원채용 All-In-One
      </div>
    </div>
  );
}

function DeanDepartmentInfo({ user }: { user: AuthUser }) {
  if (user.role !== "DEAN" || !user.departmentCode) return null;
  return (
    <div
      style={{
        padding: "12px 16px",
        borderTop: "1px solid rgba(255,255,255,0.08)",
      }}
    >
      <div
        style={{
          fontSize: 10,
          color: "var(--sidebar-section)",
          marginBottom: 4,
        }}
      >
        소속 학과
      </div>
      <div
        style={{
          fontSize: 12,
          color: "var(--sidebar-text)",
        }}
      >
        {user.departmentCode}
      </div>
    </div>
  );
}

export default function Sidebar({
  user,
  viewableResources,
}: {
  user: AuthUser;
  viewableResources: string[];
}) {
  const pathname = usePathname();
  const baseMenu = getMenuForRole(user.role);
  const menu = filterMenuByResources(baseMenu, viewableResources);

  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(max-width: 767px)");
    setIsMobile(mq.matches);
    const handler = (e: MediaQueryListEvent) => {
      setIsMobile(e.matches);
      setMobileMenuOpen(false);
    };
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  if (isMobile) {
    return (
      <>
        {/* Fixed top bar */}
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            height: 48,
            background: "#0a1f14",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            padding: "0 12px",
            zIndex: 100,
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div
              style={{
                width: 30,
                height: 30,
                borderRadius: "50%",
                background: "rgba(255,255,255,0.85)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Image
                src="/logo_SKKU_colored.png"
                alt="SKKU"
                width={20}
                height={20}
                style={{ objectFit: "contain" }}
                unoptimized
              />
            </div>
            <span style={{ color: "#fff", fontSize: 13, fontWeight: 700 }}>
              성균관대학교
            </span>
          </div>
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            style={{
              background: "transparent",
              border: "none",
              color: "#fff",
              cursor: "pointer",
              padding: 4,
            }}
          >
            {mobileMenuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>

        {/* Full-screen overlay menu */}
        {mobileMenuOpen && (
          <div
            style={{
              position: "fixed",
              top: 48,
              left: 0,
              right: 0,
              bottom: 0,
              background: "#0a1f14",
              zIndex: 99,
              display: "flex",
              flexDirection: "column",
              overflowY: "auto",
            }}
          >
            <div style={{ paddingTop: 16 }}>
              <MenuContent
                menu={menu}
                pathname={pathname}
                onItemClick={() => setMobileMenuOpen(false)}
              />
            </div>
            <div style={{ marginTop: "auto" }}>
              <DeanDepartmentInfo user={user} />
              <UserMenu user={user} />
            </div>
          </div>
        )}
      </>
    );
  }

  return (
    <aside
      style={{
        width: 180,
        background: "var(--sidebar-bg)",
        padding: "20px 0",
        flexShrink: 0,
        position: "fixed",
        top: 0,
        left: 0,
        bottom: 0,
        display: "flex",
        flexDirection: "column",
        zIndex: 50,
        overflowY: "auto",
      }}
    >
      {/* Logo + Title */}
      <LogoBlock />

      {/* Menu */}
      <MenuContent menu={menu} pathname={pathname} />

      {/* Dean department info */}
      <DeanDepartmentInfo user={user} />

      {/* User info at bottom */}
      <UserMenu user={user} />
    </aside>
  );
}

